"""Internal helpers for building Mantle insertion-point hook payloads."""

from __future__ import annotations

from typing import Optional, Tuple

from rasa.mantle.hooks.payloads import ChannelInfo


def output_channel_name(output_channel: object) -> Optional[str]:
    """Best-effort channel name for hook payloads (tolerates test doubles)."""
    name_attr = getattr(output_channel, "name", None)
    if callable(name_attr):
        try:
            return str(name_attr())
        except Exception:
            return type(output_channel).__name__
    if isinstance(name_attr, str):
        return name_attr
    return type(output_channel).__name__


def hook_identity() -> Tuple[str, ChannelInfo]:
    """Return ``(sender_id, channel)`` from the ambient turn context.

    ``MessageTurnContext`` always carries ``sender_id`` and ``output_channel``,
    so this only reads those fields. Callers must run inside an established
    turn; outside one, :func:`current_turn_context` raises ``LookupError``.
    """
    from rasa.mantle.orchestration.turn_context import current_turn_context

    ctx = current_turn_context()
    return ctx.sender_id, ChannelInfo(name=output_channel_name(ctx.output_channel))
